    @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g); if(r==42 && g.length>0 && g[0]==PackageManager.PERMISSION_GRANTED)startLocation(); view.invalidate();}
    void registerBattery(){batteryReceiver=new BatteryReceiver(view); if(Build.VERSION.SDK_INT>=33) registerReceiver(batteryReceiver,new IntentFilter(Intent.ACTION_BATTERY_CHANGED),Context.RECEIVER_NOT_EXPORTED); else registerReceiver(batteryReceiver,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));}
